   163	static int ptls_pem_parse_private_key(char const *pem_fname, ptls_asn1_pkcs8_private_key_t *pkey,
   164	                                      ptls_minicrypto_log_ctx_t *log_ctx)
   165	{
   166	    size_t nb_keys = 0;
   167	    int ret = ptls_load_pem_objects(pem_fname, "PRIVATE KEY", &pkey->vec, 1, &nb_keys);
   168	
   169	    if (ret == 0) {
   170	        if (nb_keys != 1) {
   171	            ret = PTLS_ERROR_PEM_LABEL_NOT_FOUND;
   172	        }
   173	    }
   174	
   175	    if (ret == 0 && nb_keys == 1) {
   176	        int decode_error = 0;
   177	
   178	        if (log_ctx != NULL) {
   179	            log_ctx->fn(log_ctx->ctx, "\nFound PRIVATE KEY, length = %d bytes\n", (int)pkey->vec.len);
   180	        }
   181	
   182	        (void)ptls_minicrypto_asn1_decode_private_key(pkey, &decode_error, log_ctx);
   183	
   184	        if (decode_error != 0) {
   185	            ret = decode_error;
   186	        }
   187	    }
   188	
   189	    return ret;
   190	}
